// Obtener respuesta de Gemini
const geminiResponse = $input.item.json.candidates[0].content.parts[0].text;

// Limpiar posible markdown residual
let cleanedJSON = geminiResponse
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Parsear a objeto
let eventData;
try {
  eventData = JSON.parse(cleanedJSON);
} catch (error) {
  throw new Error(`Error parseando respuesta de Gemini: ${error.message}. Respuesta: ${cleanedJSON}`);
}

// Validaciones críticas
if (!eventData.accion) {
  throw new Error('Falta campo requerido: accion');
}
if (!eventData.titulo && eventData.accion !== 'eliminar') {
  throw new Error('Falta campo requerido: titulo');
}

// Procesar fecha - asegurar formato YYYY-MM-DD
const now = new Date();
let fechaEvento = eventData.fecha;

if (!fechaEvento || fechaEvento === '' || fechaEvento === 'null') {
  fechaEvento = now.toISOString().split('T')[0];
}

// Validar formato de fecha
if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaEvento)) {
  throw new Error(`Formato de fecha inválido: ${fechaEvento}. Debe ser YYYY-MM-DD`);
}

// Procesar horas - asegurar formato HH:MM
let horaInicio = eventData.hora_inicio || '09:00';
let horaFin = eventData.hora_fin;

// Si no hay hora_fin, calcular según duración
if (!horaFin || horaFin === '' || horaFin === 'null') {
  const duracion = eventData.duracion_minutos || 60;
  const [horas, minutos] = horaInicio.split(':').map(Number);
  const inicioDate = new Date(2000, 0, 1, horas, minutos);
  const finDate = new Date(inicioDate.getTime() + duracion * 60000);
  horaFin = `${String(finDate.getHours()).padStart(2, '0')}:${String(finDate.getMinutes()).padStart(2, '0')}`;
}

// Formatear para Google Calendar API
eventData.start = {
  dateTime: `${fechaEvento}T${horaInicio}:00`,
  timeZone: 'America/Bogota'
};

eventData.end = {
  dateTime: `${fechaEvento}T${horaFin}:00`,
  timeZone: 'America/Bogota'
};

// Configurar recordatorios/alarmas
const alarmasArray = Array.isArray(eventData.alarmas) ? eventData.alarmas : [15, 60];
eventData.reminders = {
  useDefault: false,
  overrides: alarmasArray.map(minutos => ({
    method: 'popup',
    minutes: Number(minutos)
  }))
};

// Preparar descripción completa
let descripcionCompleta = eventData.descripcion || '';
if (eventData.proyecto) {
  descripcionCompleta += `\n\n📁 Proyecto: ${eventData.proyecto}`;
}
if (eventData.contacto) {
  descripcionCompleta += `\n👤 Contacto: ${eventData.contacto}`;
}
eventData.descripcion_completa = descripcionCompleta.trim();

// Preparar invitados en formato Google Calendar
if (eventData.invitados && Array.isArray(eventData.invitados) && eventData.invitados.length > 0) {
  eventData.attendees = eventData.invitados
    .filter(email => email && email.includes('@'))
    .map(email => ({ email: email.trim() }));
} else {
  eventData.attendees = [];
}

// Asegurar que color sea string
if (eventData.color) {
  eventData.color = String(eventData.color);
}

// Guardar datos originales del usuario para respuesta
eventData.mensaje_original = $('Webhook').item.json.message;
eventData.user_id = $('Webhook').item.json.user_id || 'unknown';

return { json: eventData };
